let tutorials=[],currentIndex=0;const tutorialsPerPage=100;async function loadTutorials(){try{let t=await fetch("https://www.tutorial-expert.com/tutorials.txt");if(!t.ok)throw Error("Failed to fetch tutorials file");let l=await t.text();tutorials=l.split("\n").map(t=>{try{return JSON.parse(t)}catch(l){return null}}).filter(t=>null!==t),displayTutorials()}catch(e){console.error("Error loading tutorials:",e)}}function displayTutorials(){let t=document.getElementById("tutorial-list"),l=tutorials.slice(currentIndex,currentIndex+100);l.forEach(l=>{let e=document.createElement("span");e.classList.add("tutorial-item"),e.innerHTML=`<a href="/${l.file}">${l.title}</a>`,t.appendChild(e)}),(currentIndex+=100)>=tutorials.length&&(document.getElementById("load-more-btn").style.display="none")}window.onload=loadTutorials,document.getElementById("load-more-btn").onclick=function(){displayTutorials()};